package com.tablebridge;
import java.sql.*;
import java.nio.file.*;
import java.util.*;
import java.math.BigDecimal;

/** Uses only a newly created random Oracle user and verified task-owned local servers. */
public final class OracleCrossIntegration {
 static int checks;
 static void check(boolean ok,String message){checks++;if(!ok)throw new AssertionError(message);}
 static final List<String> F=List.of("id","amount","note","payload","created","enabled");
 public static void main(String[] args){try{run(args);}catch(Throwable failure){failure.printStackTrace();System.exit(1);}}
 static void run(String[] args)throws Exception{
  Properties p=new Properties();p.load(System.in);String schema="TB_TEST_"+UUID.randomUUID().toString().replace("-", "").substring(0,12).toUpperCase(Locale.ROOT),pass="Tb_"+UUID.randomUUID().toString().replace("-", "").substring(0,20);
  boolean created=false;
  try(Connection admin=DriverManager.getConnection(p.getProperty("url"),p.getProperty("user"),p.getProperty("password"));Connection my=DriverManager.getConnection("jdbc:mysql://127.0.0.1:33316/?allowPublicKeyRetrieval=true&useSSL=false&serverTimezone=UTC","root","");Connection pg=DriverManager.getConnection("jdbc:postgresql://127.0.0.1:33317/postgres",System.getProperty("user.name"),"")){
   CrossIntegration.verifyDirectory(my,"SELECT @@datadir",args[0]);CrossIntegration.verifyDirectory(pg,"SHOW data_directory",args[1]);
   try(Statement s=admin.createStatement();ResultSet r=s.executeQuery("SELECT sys_context('USERENV','CON_NAME') FROM dual")){check(r.next()&&r.getString(1).equalsIgnoreCase(p.getProperty("container")),"explicit test PDB confirmed");}
   RowCopier.execute(admin,"CREATE USER "+schema+" IDENTIFIED BY \""+pass+"\" DEFAULT TABLESPACE USERS QUOTA 64M ON USERS");created=true;
   try{
    RowCopier.execute(admin,"GRANT CREATE SESSION,CREATE TABLE,CREATE VIEW,CREATE PROCEDURE,CREATE SEQUENCE,CREATE TYPE,CREATE TRIGGER TO "+schema);
    RowCopier.execute(my,"CREATE DATABASE "+schema+" CHARACTER SET utf8mb4");RowCopier.execute(pg,"CREATE SCHEMA "+Engine.POSTGRES.quote(schema));
    try(Connection ora=DriverManager.getConnection(p.getProperty("url"),schema,pass)){
     RowCopier.execute(my,"SET SESSION sql_mode='STRICT_ALL_TABLES,NO_AUTO_VALUE_ON_ZERO'");RowCopier.execute(pg,"SET TIME ZONE 'UTC'");SpecialValues.oracleSession(ora);
     for(var e:List.of(Engine.MYSQL,Engine.POSTGRES,Engine.ORACLE)){
      Connection c=e==Engine.MYSQL?my:e==Engine.POSTGRES?pg:ora;
      if(e==Engine.ORACLE){var ddl=CrossEngineDdl.build(Engine.POSTGRES,e,schema,"source",columns(Engine.POSTGRES),List.of("id"));RowCopier.execute(c,ddl.sql());}
      else RowCopier.execute(c,"CREATE TABLE "+e.qualified(schema,"source")+(e==Engine.MYSQL?"(id bigint PRIMARY KEY AUTO_INCREMENT,amount decimal(20,4),note varchar(100),payload blob,created datetime(6),enabled boolean)":"(id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,amount numeric(20,4),note varchar(100),payload bytea,created timestamp(6),enabled boolean)"));seed(c,e,schema);
     }
     for(Engine other:List.of(Engine.MYSQL,Engine.POSTGRES)){
      Connection c=other==Engine.MYSQL?my:pg;
      exercise(ora,c,Engine.ORACLE,other,schema,false);exercise(c,ora,other,Engine.ORACLE,schema,false);
      exercise(ora,c,Engine.ORACLE,other,schema,true);exercise(c,ora,other,Engine.ORACLE,schema,true);
     }
     special(ora,pg,my,schema);
     objects(ora,pg,my,schema);
    }
   }finally{
    my.setAutoCommit(true);pg.setAutoCommit(true);
    RowCopier.execute(my,"DROP DATABASE IF EXISTS "+schema);RowCopier.execute(pg,"DROP SCHEMA IF EXISTS "+Engine.POSTGRES.quote(schema)+" CASCADE");
    if(created)RowCopier.execute(admin,"DROP USER "+schema+" CASCADE");System.out.println("Cleaned task schema "+schema);
   }
  }finally{p.clear();}
  String result="PASS "+checks+" Oracle/MySQL/PostgreSQL checks; four directions each JDBC and native-adapter; random schemas cleaned.\n";Files.writeString(Path.of(args[2]),result);System.out.print(result);System.exit(0);
 }
 static List<CrossEngineDdl.Column> columns(Engine e){
  if(e!=Engine.ORACLE)return CrossIntegration.columns(e);
  return List.of(CrossIntegration.col("id","number(20,0)",Types.NUMERIC,20,0,true),CrossIntegration.col("amount","number(20,4)",Types.NUMERIC,20,4,false),CrossIntegration.col("note","varchar2(100 char)",Types.VARCHAR,100,0,false),CrossIntegration.col("payload","blob",Types.BLOB,0,0,false),CrossIntegration.col("created","timestamp(6)",Types.TIMESTAMP,0,0,false),CrossIntegration.col("enabled","number(1,0)",Types.NUMERIC,1,0,false));
 }
 static void seed(Connection c,Engine e,String schema)throws Exception{
  try(PreparedStatement s=c.prepareStatement("INSERT INTO "+e.qualified(schema,"source")+" VALUES(?,?,?,?,?,?)")){
   for(int i=0;i<603;i++){s.setLong(1,i);s.setBigDecimal(2,new BigDecimal("1234567890123456.1234").add(BigDecimal.valueOf(i)));if(i%2==0)s.setNull(3,Types.VARCHAR);else s.setString(3,"中文🙂'"+i);s.setBytes(4,new byte[]{0,(byte)255,(byte)i});s.setTimestamp(5,Timestamp.valueOf("2026-10-01 12:34:56.123456"));if(e==Engine.ORACLE)s.setInt(6,i%2==0?1:0);else s.setBoolean(6,i%2==0);s.addBatch();}s.executeBatch();
  }
 }
 static void exercise(Connection src,Connection dst,Engine from,Engine to,String schema,boolean nativeAdapter)throws Exception{
  String name="from_"+from.name().toLowerCase()+"_"+to.name().toLowerCase()+(nativeAdapter?"_native":"");
  var ddl=CrossEngineDdl.build(from,to,schema,name,columns(from),List.of("id"));RowCopier.execute(dst,ddl.sql());var types=ddl.columns().stream().map(TransferPlan.Column::targetType).toList();
  src.setAutoCommit(false);dst.setAutoCommit(false);long start=System.nanoTime();
  try{
   long rows=RowCopier.copy(nativeAdapter?CrossIntegration.remote(src,from):src,nativeAdapter?CrossIntegration.remote(dst,to):dst,from,to,from.qualified(schema,"source"),to.qualified(schema,name),F,true,types,()->{},n->{});check(rows==603,"row count "+name);
   try(Statement s=dst.createStatement();ResultSet r=s.executeQuery("SELECT "+String.join(",",F.stream().map(to::quote).toList())+" FROM "+to.qualified(schema,name)+" ORDER BY "+to.quote("id"))){int i=0;while(r.next()){check(r.getLong(1)==i&&r.getBigDecimal(2).compareTo(new BigDecimal("1234567890123456.1234").add(BigDecimal.valueOf(i)))==0&&Objects.equals(r.getString(3),i%2==0?null:"中文🙂'"+i)&&Arrays.equals(r.getBytes(4),new byte[]{0,(byte)255,(byte)i})&&r.getTimestamp(5).getNanos()==123456000&&r.getInt(6)==(i%2==0?1:0),"row fidelity "+name+" "+i);i++;}check(i==603,"exact rows "+name);}
   check(RowDigest.read(src,from,from.qualified(schema,"source"),F,types,()->{}).equals(RowDigest.read(dst,to,to.qualified(schema,name),F,types,()->{})),"digest "+name);
   dst.rollback();check(TargetValidation.count(dst,to.qualified(schema,name),to)==0,"rollback "+name);
   RowCopier.copy(src,dst,from,to,from.qualified(schema,"source"),to.qualified(schema,name),F,true,types,()->{},n->{});dst.commit();check(TargetValidation.count(dst,to.qualified(schema,name),to)==603,"committed "+name);
   if(to==Engine.ORACLE){for(String sql:OracleIdentity.prepare(ddl.sql(),List.of("id"),to.qualified(schema,name)).after())RowCopier.execute(dst,sql);RowCopier.execute(dst,"INSERT INTO "+to.qualified(schema,name)+" (\"note\") VALUES('generated')");try(Statement q=dst.createStatement();ResultSet r=q.executeQuery("SELECT MAX(\"id\") FROM "+to.qualified(schema,name))){check(r.next()&&r.getLong(1)>602,"Oracle identity reseed "+name);}dst.rollback();}
   System.out.println("PASS "+name+" 603 rows "+((System.nanoTime()-start)/1e9)+"s");
  }finally{src.rollback();dst.rollback();src.setAutoCommit(true);dst.setAutoCommit(true);}
 }
 static void special(Connection ora,Connection pg,Connection my,String schema)throws Exception{
  String src=Engine.ORACLE.qualified(schema,"special");
  RowCopier.execute(ora,"CREATE TABLE "+src+" (\"id\" number(10) PRIMARY KEY,\"local_time\" timestamp(6) with local time zone,\"zoned\" timestamp(6) with time zone,\"text\" clob,\"day\" date)");
  RowCopier.execute(ora,"INSERT INTO "+src+" VALUES(1,TO_TIMESTAMP_TZ('2026-10-01 12:34:56.123456 +05:30','YYYY-MM-DD HH24:MI:SS.FF6 TZH:TZM'),TO_TIMESTAMP_TZ('2026-10-01 12:34:56.123456 +05:30','YYYY-MM-DD HH24:MI:SS.FF6 TZH:TZM'),'中文 large text',TO_DATE('2026-10-01 12:34:56','YYYY-MM-DD HH24:MI:SS'))");RowCopier.execute(ora,"INSERT INTO "+src+"(\"id\") VALUES(2)");
  var cols=List.of(CrossIntegration.col("id","number(10,0)",Types.NUMERIC,10,0,false),CrossIntegration.col("local_time","timestamp(6) with local time zone",Types.TIMESTAMP_WITH_TIMEZONE,0,0,false),CrossIntegration.col("zoned","timestamp(6) with time zone",Types.TIMESTAMP_WITH_TIMEZONE,0,0,false),CrossIntegration.col("text","clob",Types.CLOB,0,0,false),CrossIntegration.col("day","date",Types.DATE,0,0,false));
  for(Engine e:List.of(Engine.POSTGRES,Engine.MYSQL)){
   Connection dst=e==Engine.POSTGRES?pg:my;var d=CrossEngineDdl.build(Engine.ORACLE,e,schema,"special_dst",cols,List.of("id"));RowCopier.execute(dst,d.sql());var fields=cols.stream().map(CrossEngineDdl.Column::name).toList();var types=d.columns().stream().map(TransferPlan.Column::targetType).toList();
   dst.setAutoCommit(false);check(RowCopier.copy(ora,dst,Engine.ORACLE,e,src,e.qualified(schema,"special_dst"),fields,false,types,()->{},n->{})==2,"Oracle special types to "+e);check(RowDigest.read(ora,Engine.ORACLE,src,fields,types,()->{}).equals(RowDigest.read(dst,e,e.qualified(schema,"special_dst"),fields,types,()->{})),"special digest "+e);dst.commit();dst.setAutoCommit(true);
   if(e==Engine.POSTGRES){var back=CrossEngineDdl.build(e,Engine.ORACLE,schema,"special_back",List.of(CrossIntegration.col("id","numeric(10,0)",Types.NUMERIC,10,0,false),CrossIntegration.col("local_time","timestamp(6) with time zone",Types.TIMESTAMP_WITH_TIMEZONE,0,0,false),CrossIntegration.col("zoned","timestamp(6) with time zone",Types.TIMESTAMP_WITH_TIMEZONE,0,0,false),CrossIntegration.col("text","text",Types.LONGVARCHAR,0,0,false),CrossIntegration.col("day","timestamp(0)",Types.TIMESTAMP,0,0,false)),List.of("id"));RowCopier.execute(ora,back.sql());var bt=back.columns().stream().map(TransferPlan.Column::targetType).toList();ora.setAutoCommit(false);check(RowCopier.copy(pg,ora,e,Engine.ORACLE,e.qualified(schema,"special_dst"),Engine.ORACLE.qualified(schema,"special_back"),fields,false,bt,()->{},n->{})==2,"PG timezone to Oracle");check(RowDigest.read(pg,e,e.qualified(schema,"special_dst"),fields,bt,()->{}).equals(RowDigest.read(ora,Engine.ORACLE,Engine.ORACLE.qualified(schema,"special_back"),fields,bt,()->{})),"timezone return digest");ora.commit();ora.setAutoCommit(true);}
  }
 }
 static void objects(Connection ora,Connection pg,Connection my,String schema)throws Exception{
  for(Engine from:List.of(Engine.ORACLE,Engine.MYSQL,Engine.POSTGRES))for(Engine to:List.of(Engine.ORACLE,Engine.MYSQL,Engine.POSTGRES))if(from!=to&&(from==Engine.ORACLE||to==Engine.ORACLE)){
   Connection dst=to==Engine.ORACLE?ora:to==Engine.POSTGRES?pg:my;String n="view_"+from.name().toLowerCase(),table="from_"+from.name().toLowerCase()+"_"+to.name().toLowerCase();
   var v=PortableView.convert(from,to,schema,schema,n,"CREATE VIEW "+from.qualified(schema,"v")+" AS SELECT "+from.quote("id")+" FROM "+from.qualified(schema,"source")+" WHERE "+from.quote("id")+">=100",Map.of("source",table));RowCopier.execute(dst,v.sql());check(TargetValidation.count(dst,to.qualified(schema,n),to)==503,"view conversion "+from+" to "+to);
   if(to!=Engine.MYSQL)RowCopier.execute(dst,CrossStructure.comment(to,schema,table,"note","中文 O'Brien"));RowCopier.execute(dst,CrossStructure.index(to,schema,table,new CrossStructure.Index("ix_"+from.name(),List.of("note"),List.of(false),false)));
   RowCopier.execute(dst,CrossStructure.check(to,schema,table,"ck_"+from.name(),"amount >= 0",Set.copyOf(F)));
  }
  for(Engine e:List.of(Engine.ORACLE,Engine.POSTGRES,Engine.MYSQL)){
   Connection c=e==Engine.ORACLE?ora:e==Engine.POSTGRES?pg:my;String fn=e.qualified(schema,"plus_one");
   if(e==Engine.ORACLE){RowCopier.execute(c,"CREATE FUNCTION "+fn+" (\"x\" NUMBER) RETURN NUMBER IS BEGIN RETURN \"x\"+1; END;");}
   else{var arg=new PortableRoutine.Argument("x",CrossIntegration.col("x","number(10,0)",Types.NUMERIC,10,0,false));RowCopier.execute(c,PortableRoutine.create(Engine.ORACLE,e,schema,"plus_one",List.of(arg),arg.type(),"CREATE FUNCTION src.f(x NUMBER) RETURN NUMBER IS BEGIN RETURN x+1; END;"));}
   try(Statement q=c.createStatement();ResultSet r=q.executeQuery("SELECT "+fn+"(12)"+(e==Engine.ORACLE?" FROM dual":""))){check(r.next()&&r.getBigDecimal(1).compareTo(BigDecimal.valueOf(13))==0,"function calls "+e);}
  }
  String child=Engine.ORACLE.qualified(schema,"child");RowCopier.execute(ora,"CREATE TABLE "+child+" (\"id\" NUMBER(20) PRIMARY KEY,\"parent_id\" NUMBER(20))");RowCopier.execute(ora,CrossStructure.foreignKey(Engine.ORACLE,schema,"child",new CrossStructure.ForeignKey("child_fk",List.of("parent_id"),"source",List.of("id"),"CASCADE","NO_ACTION")));boolean refused=false;try{RowCopier.execute(ora,"INSERT INTO "+child+" VALUES(1,99999)");}catch(SQLException ex){refused=true;}check(refused,"Oracle foreign key enforced");
  String trig=Engine.ORACLE.qualified(schema,"trig");RowCopier.execute(ora,"CREATE TABLE "+trig+" (\"id\" NUMBER,\"note\" VARCHAR2(100))");RowCopier.execute(ora,"CREATE TRIGGER "+Engine.ORACLE.qualified(schema,"trig_before")+" BEFORE INSERT ON "+trig+" FOR EACH ROW BEGIN :NEW.\"note\" := 'triggered'; END;");RowCopier.execute(ora,"INSERT INTO "+trig+"(\"id\") VALUES(1)");try(Statement q=ora.createStatement();ResultSet r=q.executeQuery("SELECT \"note\" FROM "+trig)){check(r.next()&&r.getString(1).equals("triggered"),"reviewed Oracle trigger executes");}
  var seq=new PortableSequence.Spec(java.math.BigInteger.valueOf(21),java.math.BigInteger.valueOf(2),java.math.BigInteger.ONE,java.math.BigInteger.valueOf(1000),0,false);
  for(Engine e:List.of(Engine.ORACLE,Engine.POSTGRES)){Connection c=e==Engine.ORACLE?ora:pg;RowCopier.execute(c,PortableSequence.create(e,schema,"seq",seq));try(Statement q=c.createStatement();ResultSet r=q.executeQuery(e==Engine.ORACLE?"SELECT "+e.qualified(schema,"seq")+".NEXTVAL FROM dual":"SELECT nextval('"+e.qualified(schema,"seq")+"')")){check(r.next()&&r.getLong(1)==21,"sequence "+e);}}
 }

}
